<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserConsentedScopes\Domain\ValueObject\Accessor\UserConsentedScopesGrantedAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserConsentedScopesGrantedAccessor trait.
 *
 * Covers null default, string/VO assignment via withGranted,
 * getGranted/granted accessors, and isGrantedChanged with/without original.
 */
class UserConsentedScopesGrantedAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withGranted creates a new instance with the Granted set
     * from a string value, and getGranted returns the primitive string.
     */
    public function testWithGrantedFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserConsentedScopesGrantedAccessorUnitTest();

        // Act
        $result = $holder->withGranted(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isGranted());
    }
    /**
     * Asserts that withgranted has access to the value object
     * from a string value, and getGranted returns the primitive string.
     */
    public function testWithGrantedFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserConsentedScopesGrantedAccessorUnitTest();

        // Act
        $result = $holder->withGranted(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->granted()->value());
    }
    public function testChangedGranted(): void
    {
        // Arrange
        $holder = new ImplWithUserConsentedScopesGrantedAccessorUnitTest();
        $original = $holder->withGranted(true);
        $same = $holder->withGranted(true);
        $modified = $holder->withGranted(false);

        // Act
        $unchanged = $holder->isGrantedChanged();
        $withSame = $original->isGrantedChanged($same);
        $withDiferent = $original->isGrantedChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserConsentedScopesGrantedAccessorUnitTest
{
    use UserConsentedScopesGrantedAccessor;
}
